type agreementUsedFootnoteParagraph struct {
	Ordinal int
	Kind    string
	Lines   []text.Segment
}
type agreementUsedFootnoteDeclaration struct {
	Node          int
	Label, Parent string
	Bounds        agreementNativeDefinitionSpan
	Found         bool
	Paragraphs    []agreementUsedFootnoteParagraph
}
type agreementUsedFootnoteOwner struct {
	Field, Note, Node, Paragraph, Ordinal, Line int
	Label                                       string
}

// Used definitions remain in the document tree, with their original consumed bounds.
func agreementUsedFootnoteReading(body string) []agreementUsedFootnoteDeclaration {
	context := parser.NewContext()
	context.Set(agreementFootnoteTargetsKey, make(map[string]int))
	var unused []*extast.Footnote
	context.Set(agreementUnusedFootnoteNodesKey, &unused)
	spans := make(map[ast.Node]agreementNativeDefinitionSpan)
	context.Set(agreementNativeDefinitionSpansKey, spans)
	doc := agreementNativeOwnerGrammar.Parser().Parse(text.NewReader([]byte(body)), parser.WithContext(context))
	var notes []agreementUsedFootnoteDeclaration
	node := 0
	if err := ast.Walk(doc, func(n ast.Node, entering bool) (ast.WalkStatus, error) {
		if !entering {
			return ast.WalkContinue, nil
		}
		at := node
		node++
		footnote, ok := n.(*extast.Footnote)
		if !ok {
			return ast.WalkContinue, nil
		}
		bounds, found := spans[n]
		r := agreementUsedFootnoteDeclaration{Node: at, Label: string(footnote.Ref), Bounds: bounds, Found: found}
		if n.Parent() != nil {
			r.Parent = n.Parent().Kind().String()
		}
		ordinal := 0
		for child := n.FirstChild(); child != nil; child = child.NextSibling() {
			if child.Kind() != ast.KindParagraph {
				continue
			}
			p := agreementUsedFootnoteParagraph{Ordinal: ordinal, Kind: child.Kind().String()}
			ordinal++
			for i := range child.Lines().Len() {
				p.Lines = append(p.Lines, child.Lines().At(i))
			}
			r.Paragraphs = append(r.Paragraphs, p)
		}
		notes = append(notes, r)
		return ast.WalkContinue, nil
	}); err != nil {
		panic(err)
	}
	return notes
}

// A selected check field belongs to one later paragraph of a used native definition.
func agreementUsedFootnoteOwners(check *agreementNativeCheckSource, notes []agreementUsedFootnoteDeclaration) ([]agreementUsedFootnoteOwner, bool) {
	var owners []agreementUsedFootnoteOwner
	used := make(map[graph.Span]bool)
	for fi, field := range check.Fields {
		if !slices.Contains(field.Targets, "B") {
			continue
		}
		if !field.Code || field.Comment || field.Escaped || field.DefinitionOwner >= 0 || field.CodeOwner >= 0 || len(field.Targets) != 1 || field.Word != "[[B]]" || field.Span.Start < 0 || field.Span.Stop-field.Span.Start != 5 || used[field.Span] {
			return nil, false
		}
		candidate := agreementUsedFootnoteOwner{}
		found := false
		for ni := range notes {
			note := &notes[ni]
			if !note.Found || note.Parent != extast.KindFootnoteList.String() || note.Label == "" || note.Bounds.Parent == "" || note.Bounds.Span.Start < 0 || note.Bounds.Span.Stop <= note.Bounds.Span.Start || note.Bounds.Label.Start < note.Bounds.Span.Start || note.Bounds.Label.Stop > note.Bounds.Span.Stop || note.Bounds.Label.Stop <= note.Bounds.Label.Start || field.Span.Start < note.Bounds.Span.Start || field.Span.Stop > note.Bounds.Span.Stop {
				continue
			}
			for pi := range note.Paragraphs {
				paragraph := &note.Paragraphs[pi]
				if paragraph.Ordinal < 1 || paragraph.Kind != ast.KindParagraph.String() {
					continue
				}
				for li, line := range paragraph.Lines {
					if field.Span.Start < line.Start || field.Span.Stop > line.Stop {
						continue
					}
					if found {
						return nil, false
					}
					found = true
					candidate = agreementUsedFootnoteOwner{Field: fi, Note: ni, Node: note.Node, Label: note.Label, Paragraph: pi, Ordinal: paragraph.Ordinal, Line: li}
				}
			}
		}
		if !found {
			return nil, false
		}
		used[field.Span] = true
		owners = append(owners, candidate)
	}
	return owners, len(owners) > 0
}

// Equal-width private targets preserve the native declaration and every other byte.
func agreementUsedFootnotePrivate(body string, check *agreementNativeCheckSource, notes []agreementUsedFootnoteDeclaration) (string, []agreementUsedFootnoteOwner, bool) {
	if strings.Contains(body, "q") {
		return "", nil, false
	}
	owners, ok := agreementUsedFootnoteOwners(check, notes)
	if !ok {
		return "", nil, false
	}
	private := []byte(body)
	for _, owner := range owners {
		field := check.Fields[owner.Field]
		note := &notes[owner.Note]
		if field.Span.Stop > len(body) || note.Bounds.Span.Stop > len(body) || body[field.Span.Start:field.Span.Stop] != field.Word {
			return "", nil, false
		}
		private[field.Span.Start+2] = 'q'
	}
	return string(private), owners, true
}

