func TestAgreementUsedFootnoteDifferences(t *testing.T) {
	t.Parallel()
	witnesses := agreementUsedFootnoteWitnesses()
	for wi := range witnesses {
		w := &witnesses[wi]
		t.Run(w.Name, func(t *testing.T) {
			t.Parallel()
			c := agreementCase{Body: w.Body}
			raw, page := agreementIsolatedPage(t, c)
			failures := agreementPageFailures(w.Body, &raw, &page)
			failures = append(failures, agreementFragmentFailures(t, []agreementCase{c}, []agreementHTML{page})[0]...)
			seen := 0
			for _, f := range failures {
				if w.Selected[agreementSignature(&f)] != 1 {
					continue
				}
				seen++
				k, a, v := agreementUsedFootnoteDifference(c, &f, raw.HTML, &page, failures)
				if k != "debt" || a != "#1011 stage 4" || v != "judge" {
					t.Fatal("caught: used footnote lost its declared authority")
				}
				for _, alter := range []struct {
					Name   string
					Change func(*agreementFailure)
				}{
					{"property", func(f *agreementFailure) { f.Property = "P2" }}, {"identity", func(f *agreementFailure) { f.Identity = "other" }}, {"direction", func(f *agreementFailure) { f.Direction = "other" }}, {"target", func(f *agreementFailure) { f.Tuple.Target = "outside" }}, {"role", func(f *agreementFailure) { f.Tuple.SourceRole = "other" }}, {"state", func(f *agreementFailure) { f.Tuple.State = "other" }}, {"section", func(f *agreementFailure) { f.Tuple.Section = "other" }}, {"multiplicity", func(f *agreementFailure) { f.Multiplicity++ }}, {"cut", func(f *agreementFailure) { f.Cut = "other" }}, {"fragment", func(f *agreementFailure) { f.Fragment = "other" }}, {"page", func(f *agreementFailure) { f.PagePresent = true }}, {"judge", func(f *agreementFailure) { f.JudgeAccepted = true }}, {"excerpt", func(f *agreementFailure) { f.ExcerptFound = true }},
				} {
					t.Run(alter.Name, func(t *testing.T) {
						changed := f
						alter.Change(&changed)
						kind, authority, wrong := agreementUsedFootnoteDifference(c, &changed, raw.HTML, &page, failures)
						if kind != "" || authority != "" || wrong != "" {
							t.Fatal("caught: used footnote borrowed another signed face")
						}
					})
				}
				for _, other := range []agreementCase{{Body: w.Body + "\n"}, {Body: w.Body, Title: "A"}, {Body: w.Body, Companions: capturedBodies{"Notes/Other.md": "outside"}}} {
					kind, authority, wrong := agreementUsedFootnoteDifference(other, &f, raw.HTML, &page, failures)
					if kind != "" || authority != "" || wrong != "" {
						t.Fatal("caught: used footnote borrowed another complete body or context")
					}
				}
				for i := range failures {
					missing := slices.Delete(slices.Clone(failures), i, i+1)
					k, a, v = agreementUsedFootnoteDifference(c, &f, raw.HTML, &page, missing)
					if k != "" || a != "" || v != "" {
						t.Fatal("caught: used footnote borrowed an incomplete whole signed pool")
					}
				}
				extra := append(slices.Clone(failures), f)
				k, a, v = agreementUsedFootnoteDifference(c, &f, raw.HTML, &page, extra)
				if k != "" || a != "" || v != "" {
					t.Fatal("caught: used footnote borrowed another whole signed pool")
				}
				changed := page
				changed.Headings = append(slices.Clone(page.Headings), "outside")
				k, a, v = agreementUsedFootnoteDifference(c, &f, raw.HTML, &changed, failures)
				if k != "" || a != "" || v != "" {
					t.Fatal("caught: used footnote borrowed another whole public ledger")
				}
				k, a, v = agreementUsedFootnoteDifference(c, &f, raw.HTML+"<code>outside</code>", &page, failures)
				if k != "" || a != "" || v != "" {
					t.Fatal("caught: used footnote borrowed changed field-free code text")
				}
			}
			if seen != len(w.Selected) {
				t.Fatal("used footnote selected receipt setup")
			}
		})
	}
}

func agreementUsedFootnoteDifference(c agreementCase, f *agreementFailure, raw string, page *agreementHTML, failures []agreementFailure) (kind, authority, wrong string) {
	if f == nil || page == nil || c.Title != "" || len(c.Companions) != 0 || f.Property != "P1" || f.Identity != "citation-occurrences" || f.Direction != "page-only" || f.Multiplicity < 1 || f.Fragment != "" || f.Cut != "" || f.PagePresent || f.JudgeAccepted || f.ExcerptFound {
		return "", "", ""
	}
	witnesses := agreementUsedFootnoteWitnesses()
	for wi := range witnesses {
		w := &witnesses[wi]
		if c.Body != w.Body {
			continue
		}
		if w.Selected[agreementSignature(f)] != 1 {
			return "", "", ""
		}
		native := agreementNativeOwnerReading(c.Body)
		check := agreementNativeCheckReading(c.Body, native)
		notes := agreementUsedFootnoteReading(c.Body)
		parts, pok := agreementCodeWindowParts(raw)
		private, owners, ok := agreementUsedFootnotePrivate(c.Body, &check, notes)
		if !ok || !pok || private != w.Private || !cmp.Equal(owners, w.Owners) || !cmp.Equal(notes, w.Notes) || !cmp.Equal(native, w.Native) || !cmp.Equal(check, w.Check) || !cmp.Equal(agreementNativeHTMLAddressSites(c.Body), w.HTML) || !cmp.Equal(agreementNativeProseAddressTreeReading(c.Body, nil), w.Tree) || !cmp.Equal(judge.LinkTargets(c.Body), w.Targets) || !cmp.Equal(parts, w.Parts) || !cmp.Equal(*page, w.Page) || !maps.Equal(agreementUsedFootnoteCurrent(failures), w.Signatures) {
			return "", "", ""
		}
		return "debt", "#1011 stage 4", "judge"
	}
	return "", "", ""
}

func TestAgreementUsedFootnoteSource(t *testing.T) {
	t.Parallel()
	witnesses := agreementUsedFootnoteWitnesses()
	for wi := range witnesses {
		w := &witnesses[wi]
		t.Run(w.Name, func(t *testing.T) {
			t.Parallel()
			for _, tc := range []struct {
				Body  string
				Check agreementNativeCheckSource
			}{{w.Body, w.Check}, {w.Private, w.PrivateCheck}} {
				native := agreementNativeOwnerReading(tc.Body)
				if diff := cmp.Diff(w.Native, native); diff != "" {
					t.Fatalf("caught: complete used footnote native facts (-want +got):\n%s", diff)
				}
				if diff := cmp.Diff(tc.Check, agreementNativeCheckReading(tc.Body, native)); diff != "" {
					t.Fatalf("caught: complete used footnote physical fields (-want +got):\n%s", diff)
				}
				if diff := cmp.Diff(w.Notes, agreementUsedFootnoteReading(tc.Body)); diff != "" {
					t.Fatalf("caught: complete used footnote declarations (-want +got):\n%s", diff)
				}
				if diff := cmp.Diff(w.HTML, agreementNativeHTMLAddressSites(tc.Body)); diff != "" {
					t.Fatalf("caught: complete used footnote HTML declarations (-want +got):\n%s", diff)
				}
				if diff := cmp.Diff(w.Tree, agreementNativeProseAddressTreeReading(tc.Body, nil)); diff != "" {
					t.Fatalf("caught: complete used footnote trees (-want +got):\n%s", diff)
				}
				if diff := cmp.Diff(w.Targets, judge.LinkTargets(tc.Body)); diff != "" {
					t.Fatalf("caught: complete used footnote unchanged check targets (-want +got):\n%s", diff)
				}
			}
			private, owners, ok := agreementUsedFootnotePrivate(w.Body, &w.Check, w.Notes)
			if !ok || private != w.Private || !cmp.Equal(owners, w.Owners) {
				t.Fatal("caught: exact later used footnote ownership and only its target bytes")
			}
			expected := w.Check
			expected.Fields = slices.Clone(w.Check.Fields)
			for _, owner := range w.Owners {
				expected.Fields[owner.Field].Word = "[[q]]"
				expected.Fields[owner.Field].Targets = []string{"q"}
			}
			if !cmp.Equal(expected, w.PrivateCheck) {
				t.Fatal("caught: every unselected used footnote physical field stays identical")
			}
		})
	}
}

func TestAgreementUsedFootnotePublic(t *testing.T) {
	t.Parallel()
	witnesses := agreementUsedFootnoteWitnesses()
	for wi := range witnesses {
		w := &witnesses[wi]
		t.Run(w.Name, func(t *testing.T) {
			t.Parallel()
			for _, tc := range []struct {
				Name, Body string
				Page       agreementHTML
				Signatures map[string]int
			}{{"original", w.Body, w.Page, w.Signatures}, {"private", w.Private, w.PrivatePage, w.PrivateSignatures}} {
				t.Run(tc.Name, func(t *testing.T) {
					c := agreementCase{Body: tc.Body}
					raw, page := agreementIsolatedPage(t, c)
					if diff := cmp.Diff(tc.Page, page); diff != "" {
						t.Fatalf("caught: complete used footnote public ledger (-want +got):\n%s", diff)
					}
					parts, ok := agreementCodeWindowParts(raw.HTML)
					if diff := cmp.Diff(w.Parts, parts); !ok || diff != "" {
						t.Fatalf("caught: complete used footnote unchanged code payloads (-want +got):\n%s", diff)
					}
					failures := agreementPageFailures(tc.Body, &raw, &page)
					failures = append(failures, agreementFragmentFailures(t, []agreementCase{c}, []agreementHTML{page})[0]...)
					if !maps.Equal(tc.Signatures, agreementUsedFootnoteCurrent(failures)) {
						t.Fatal("caught: complete P0-P4 used footnote signed pools")
					}
				})
			}
			expected := maps.Clone(w.Signatures)
			for sig, n := range w.Selected {
				expected[sig] -= n
				if expected[sig] == 0 {
					delete(expected, sig)
				}
				expected[strings.Replace(sig, "Target:B ", "Target:q ", 1)] += n
			}
			if !maps.Equal(expected, w.PrivateSignatures) {
				t.Fatal("caught: every unselected used footnote receipt stays identical")
			}
			page := w.Page
			page.Citations = slices.Clone(page.Citations)
			count := 0
			for i := range page.Citations {
				if page.Citations[i].Target == "B" {
					page.Citations[i].Target = "q"
					count++
				}
			}
			if !cmp.Equal(page, w.PrivatePage) || count != len(w.Owners) {
				t.Fatal("caught: exactly the later used footnote live citations change their private target")
			}
		})
	}
}

func TestAgreementUsedFootnoteOwnershipRefusals(t *testing.T) {
	for _, w := range agreementUsedFootnoteWitnesses() {
		owner := w.Owners[0]
		for _, tc := range []struct {
			Name   string
			Change func(*agreementNativeCheckSource, []agreementUsedFootnoteDeclaration) []agreementUsedFootnoteDeclaration
		}{
			{"missing", func(_ *agreementNativeCheckSource, _ []agreementUsedFootnoteDeclaration) []agreementUsedFootnoteDeclaration {
				return nil
			}},
			{"missing fields", func(c *agreementNativeCheckSource, n []agreementUsedFootnoteDeclaration) []agreementUsedFootnoteDeclaration {
				c.Fields = nil
				return n
			}},
			{"ambiguous", func(_ *agreementNativeCheckSource, n []agreementUsedFootnoteDeclaration) []agreementUsedFootnoteDeclaration {
				return append(n, n[owner.Note])
			}},
			{"not found", func(_ *agreementNativeCheckSource, n []agreementUsedFootnoteDeclaration) []agreementUsedFootnoteDeclaration {
				n[owner.Note].Found = false
				return n
			}},
			{"unused parent", func(_ *agreementNativeCheckSource, n []agreementUsedFootnoteDeclaration) []agreementUsedFootnoteDeclaration {
				n[owner.Note].Parent = ast.KindDocument.String()
				return n
			}},
			{"absent label", func(_ *agreementNativeCheckSource, n []agreementUsedFootnoteDeclaration) []agreementUsedFootnoteDeclaration {
				n[owner.Note].Label = ""
				return n
			}},
			{"absent original parent", func(_ *agreementNativeCheckSource, n []agreementUsedFootnoteDeclaration) []agreementUsedFootnoteDeclaration {
				n[owner.Note].Bounds.Parent = ""
				return n
			}},
			{"outside definition start", func(c *agreementNativeCheckSource, n []agreementUsedFootnoteDeclaration) []agreementUsedFootnoteDeclaration {
				n[owner.Note].Bounds.Span.Start = c.Fields[owner.Field].Span.Start + 1
				n[owner.Note].Bounds.Label = graph.Span{Start: n[owner.Note].Bounds.Span.Start, Stop: n[owner.Note].Bounds.Span.Start + 1}
				return n
			}},
			{"outside definition stop", func(c *agreementNativeCheckSource, n []agreementUsedFootnoteDeclaration) []agreementUsedFootnoteDeclaration {
				n[owner.Note].Bounds.Span.Stop = c.Fields[owner.Field].Span.Start
				return n
			}},
			{"outside label", func(_ *agreementNativeCheckSource, n []agreementUsedFootnoteDeclaration) []agreementUsedFootnoteDeclaration {
				n[owner.Note].Bounds.Label.Start = n[owner.Note].Bounds.Span.Start - 1
				return n
			}},
			{"empty label", func(_ *agreementNativeCheckSource, n []agreementUsedFootnoteDeclaration) []agreementUsedFootnoteDeclaration {
				n[owner.Note].Bounds.Label.Stop = n[owner.Note].Bounds.Label.Start
				return n
			}},
			{"first paragraph", func(_ *agreementNativeCheckSource, n []agreementUsedFootnoteDeclaration) []agreementUsedFootnoteDeclaration {
				n[owner.Note].Paragraphs[owner.Paragraph].Ordinal = 0
				return n
			}},
			{"other paragraph kind", func(_ *agreementNativeCheckSource, n []agreementUsedFootnoteDeclaration) []agreementUsedFootnoteDeclaration {
				n[owner.Note].Paragraphs[owner.Paragraph].Kind = ast.KindCodeBlock.String()
				return n
			}},
			{"missing lines", func(_ *agreementNativeCheckSource, n []agreementUsedFootnoteDeclaration) []agreementUsedFootnoteDeclaration {
				n[owner.Note].Paragraphs[owner.Paragraph].Lines = nil
				return n
			}},
			{"clipped line start", func(c *agreementNativeCheckSource, n []agreementUsedFootnoteDeclaration) []agreementUsedFootnoteDeclaration {
				n[owner.Note].Paragraphs[owner.Paragraph].Lines[owner.Line].Start = c.Fields[owner.Field].Span.Stop
				return n
			}},
			{"clipped line stop", func(c *agreementNativeCheckSource, n []agreementUsedFootnoteDeclaration) []agreementUsedFootnoteDeclaration {
				n[owner.Note].Paragraphs[owner.Paragraph].Lines[owner.Line].Stop = c.Fields[owner.Field].Span.Start
				return n
			}},
			{"not check code", func(c *agreementNativeCheckSource, n []agreementUsedFootnoteDeclaration) []agreementUsedFootnoteDeclaration {
				c.Fields[owner.Field].Code = false
				return n
			}},
			{"comment", func(c *agreementNativeCheckSource, n []agreementUsedFootnoteDeclaration) []agreementUsedFootnoteDeclaration {
				c.Fields[owner.Field].Comment = true
				return n
			}},
			{"escaped", func(c *agreementNativeCheckSource, n []agreementUsedFootnoteDeclaration) []agreementUsedFootnoteDeclaration {
				c.Fields[owner.Field].Escaped = true
				return n
			}},
			{"unused definition", func(c *agreementNativeCheckSource, n []agreementUsedFootnoteDeclaration) []agreementUsedFootnoteDeclaration {
				c.Fields[owner.Field].DefinitionOwner = 0
				return n
			}},
			{"native code", func(c *agreementNativeCheckSource, n []agreementUsedFootnoteDeclaration) []agreementUsedFootnoteDeclaration {
				c.Fields[owner.Field].CodeOwner = 0
				return n
			}},
			{"multiple targets", func(c *agreementNativeCheckSource, n []agreementUsedFootnoteDeclaration) []agreementUsedFootnoteDeclaration {
				c.Fields[owner.Field].Targets = []string{"B", "other"}
				return n
			}},
			{"other word", func(c *agreementNativeCheckSource, n []agreementUsedFootnoteDeclaration) []agreementUsedFootnoteDeclaration {
				c.Fields[owner.Field].Word = "[[X]]"
				return n
			}},
			{"duplicate field", func(c *agreementNativeCheckSource, n []agreementUsedFootnoteDeclaration) []agreementUsedFootnoteDeclaration {
				c.Fields = append(c.Fields, c.Fields[owner.Field])
				return n
			}},
			{"negative field", func(c *agreementNativeCheckSource, n []agreementUsedFootnoteDeclaration) []agreementUsedFootnoteDeclaration {
				c.Fields[owner.Field].Span.Start = -1
				return n
			}},
			{"partial field", func(c *agreementNativeCheckSource, n []agreementUsedFootnoteDeclaration) []agreementUsedFootnoteDeclaration {
				c.Fields[owner.Field].Span.Stop--
				return n
			}},
		} {
			t.Run(w.Name+"/"+tc.Name, func(t *testing.T) {
				c := w.Check
				c.Fields = slices.Clone(c.Fields)
				notes := slices.Clone(w.Notes)
				for i := range notes {
					notes[i].Paragraphs = slices.Clone(notes[i].Paragraphs)
					for j := range notes[i].Paragraphs {
						notes[i].Paragraphs[j].Lines = slices.Clone(notes[i].Paragraphs[j].Lines)
					}
				}
				notes = tc.Change(&c, notes)
				if _, ok := agreementUsedFootnoteOwners(&c, notes); ok {
					t.Fatal("caught: used footnote borrowed absent, first, partial or ambiguous ownership")
				}
			})
		}
		t.Run(w.Name+"/private collision", func(t *testing.T) {
			if _, _, ok := agreementUsedFootnotePrivate(w.Body+"q", &w.Check, w.Notes); ok {
				t.Fatal("caught: used footnote private target collides")
			}
		})
		t.Run(w.Name+"/changed field bytes", func(t *testing.T) {
			body := []byte(w.Body)
			body[w.Check.Fields[owner.Field].Span.Start+2] = 'X'
			if _, _, ok := agreementUsedFootnotePrivate(string(body), &w.Check, w.Notes); ok {
				t.Fatal("caught: used footnote borrowed changed physical word bytes")
			}
		})
	}
}
